    newItems?: {
      name: string; // Item name
      description?: string; // One sentence description
      quantity?: number; // How many (default 1)
      location?: string; // inventory, worn, or location name
      equipped?: boolean; // true if currently worn/wielded
    }[];
    newStoryBeats?: {
      title: string; // Short title (3-6 words)
      description?: string; // What happened or needs to happen
      type?: "milestone" | "quest" | "revelation" | "event" | "plot_point"; // milestone, quest, revelation, event, or plot_point
      status?: "pending" | "active" | "completed" | "failed"; // pending=upcoming, active=in-progress, completed=done
    }[];
  };
